/// <summary>
/// This method checks if there is an existing <c>VendInvoiceInfoSubTable</c> record, if not we create one
/// and initialize the invoice line fields.
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext instance</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext instance</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

    switch(_dataSourceCtx.name())
    {
        case dataentitydatasourcestr(VendorInvoiceLineEntity, VendInvoiceInfoLine):
            VendInvoiceInfoLine vendInvoiceInfoLine = _dataSourceCtx.getBuffer();

            if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
            {

                METMultiSelectStringValue poSubMode = METPurchTable::find(this.PurchaseOrder).POSubMode;
                if (PurchFormLetter::getPOSubMode(poSubMode, enum2Str(METPOSubMode::EDI)) && !this.METUnitPriceInclGST)
                {
                    PurchLine purchLine = PurchLine::find(this.PurchaseOrder, this.PurchLineNumber);
                    PurchTable purchTable = PurchTable::find(this.PurchaseOrder);

                    if (purchLine.RecId && vendInvoiceInfoLine.METUnitPriceInclGST)
                    {
                        this.setUnitPriceFromInclusiveGST(vendInvoiceInfoLine, purchLine, purchTable);
                    }
                }    
            }        
    }
}

/// <summary>
/// Set unit price from inclusive gst
/// </summary>
/// <param name = "_vendInvoiceInfoLine"_vendInvoiceInfoLine></param>
/// <param name = "_purchLine">_purchLine</param>
/// <param name = "_purchTable">_purchTable</param>
private void setUnitPriceFromInclusiveGST(VendInvoiceInfoLine _vendInvoiceInfoLine, PurchLine _purchLine, PurchTable _purchTable)
{
    PurchTotals         purchTotals;
    TmpTaxWorkTrans     tmpTaxWorkTrans;        
    AmountCur           unitPriceExclGST;
    TaxAmountCur        gstAmount;
    TaxAmountCur        gstBaseAmount;
    real                gstPercent;

    purchTotals = PurchTotals::newPurchTable(_purchTable);
    purchTotals.calc();

    tmpTaxWorkTrans.setTmpData(purchTotals.tax().tmpTaxWorkTrans());

    select firstOnly tmpTaxWorkTrans
        where tmpTaxWorkTrans.InventTransId == _purchLine.InventTransId;

    if (!tmpTaxWorkTrans.RecId)
    {
        return;
    }

    gstBaseAmount = tmpTaxWorkTrans.SourceBaseAmountCur;
    gstAmount     = tmpTaxWorkTrans.SourceTaxAmountCur;

    if (!gstBaseAmount)
    {
        return;
    }

    gstPercent = (gstAmount / gstBaseAmount) * 100;

    unitPriceExclGST = _vendInvoiceInfoLine.METUnitPriceInclGST * 100/ (100 + gstPercent);

    _vendInvoiceInfoLine.PurchPrice = unitPriceExclGST;
}
